import java.io.*;

public class Main {
    static int[] parent;

    static int find(int x) {
        int root = x;
        while (parent[root] != root) root = parent[root];
        while (parent[x] != root) {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in, 1 << 16));
        in.nextToken(); int n = (int) in.nval;
        in.nextToken(); int m = (int) in.nval;
        in.nextToken(); int k = (int) in.nval;

        int[] a = new int[m], b = new int[m], t = new int[m];
        for (int i = 0; i < m; i++) {
            in.nextToken(); a[i] = (int) in.nval;
            in.nextToken(); b[i] = (int) in.nval;
            in.nextToken(); t[i] = (int) in.nval;
        }

        parent = new int[n + 1];
        int[] rnk = new int[n + 1];
        for (int i = 1; i <= n; i++) parent[i] = i;

        // Passo 1: hidrovias devem permanecer — o subgrafo delas precisa ser floresta.
        for (int i = 0; i < m; i++) {
            if (t[i] != 1) continue;
            int ra = find(a[i]), rb = find(b[i]);
            if (ra == rb) { // ciclo formado apenas por hidrovias: impossível
                System.out.println("N");
                return;
            }
            if (rnk[ra] < rnk[rb]) { int tmp = ra; ra = rb; rb = tmp; }
            parent[rb] = ra;
            if (rnk[ra] == rnk[rb]) rnk[ra]++;
        }

        // Passo 2: rodovias entre componentes distintas podem ser mantidas (floresta máxima
        // no multigrafo contraído); rodovias que criam ciclo precisam ser removidas
        // (o ciclo usa caminho de hidrovias, que não pode ser removido, então a rodovia é obrigatoriamente removida).
        long removals = 0;
        for (int i = 0; i < m; i++) {
            if (t[i] != 2) continue;
            int ra = find(a[i]), rb = find(b[i]);
            if (ra == rb) {
                removals++;
            } else {
                if (rnk[ra] < rnk[rb]) { int tmp = ra; ra = rb; rb = tmp; }
                parent[rb] = ra;
                if (rnk[ra] == rnk[rb]) rnk[ra]++;
            }
        }

        System.out.println(removals <= k ? "S" : "N");
    }
}
